const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder('utf-8', { fatal: false });

const ALWAYS_SAFE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';
const HEX = '0123456789ABCDEF';

function isHexDigit(char) {
  return (
    (char >= '0' && char <= '9') ||
    (char >= 'a' && char <= 'f') ||
    (char >= 'A' && char <= 'F')
  );
}

function pushUtf8Bytes(bytes, char) {
  for (const byte of textEncoder.encode(char)) {
    bytes.push(byte);
  }
}

export function unquote(value) {
  const bytes = [];
  let index = 0;

  while (index < value.length) {
    const char = value[index];
    if (
      char === '%' &&
      index + 2 < value.length &&
      isHexDigit(value[index + 1]) &&
      isHexDigit(value[index + 2])
    ) {
      bytes.push(Number.parseInt(value.slice(index + 1, index + 3), 16));
      index += 3;
      continue;
    }

    const codePoint = value.codePointAt(index);
    const fullChar = String.fromCodePoint(codePoint);
    pushUtf8Bytes(bytes, fullChar);
    index += fullChar.length;
  }

  return textDecoder.decode(new Uint8Array(bytes));
}

export function quote(value, safe = '', spaceAsPlus = false) {
  let output = '';

  for (const byte of textEncoder.encode(value)) {
    if (byte < 0x80) {
      const char = String.fromCharCode(byte);
      if (ALWAYS_SAFE.includes(char) || safe.includes(char)) {
        output += char;
        continue;
      }
      if (spaceAsPlus && char === ' ') {
        output += '+';
        continue;
      }
    }

    output += `%${HEX[(byte >> 4) & 0x0f]}${HEX[byte & 0x0f]}`;
  }

  return output;
}

export function unquotePlus(value) {
  return unquote(value.replaceAll('+', ' '));
}

export function quotePlus(value) {
  return quote(value, '', true);
}

export function parseQuery(query) {
  const pairs = [];
  if (query === '') {
    return pairs;
  }

  for (const field of query.split('&')) {
    if (field === '') {
      continue;
    }

    const equalsIndex = field.indexOf('=');
    if (equalsIndex === -1) {
      pairs.push({ name: unquotePlus(field), value: '', hasEquals: false });
    } else {
      pairs.push({
        name: unquotePlus(field.slice(0, equalsIndex)),
        value: unquotePlus(field.slice(equalsIndex + 1)),
        hasEquals: true,
      });
    }
  }

  return pairs;
}

export function serializeQuery(pairs) {
  return pairs
    .map((pair) => {
      const name = quotePlus(pair.name);
      return pair.hasEquals ? `${name}=${quotePlus(pair.value)}` : name;
    })
    .join('&');
}

import { isIP } from 'node:net';
import { domainToASCII } from 'node:url';

import { quote, unquote } from './pythonCodec.mjs';

export const PATH_SAFE = "/%:@!$&'()*+,;=";
export const FRAGMENT_SAFE = "/%:@!$&'()*+,;=?";

const INVALID_HOST_CHARS = /[!@#$%^&'"*()+=:;/]/;
const HOST_ERROR_SUFFIX =
  "Host strings must have at least one non-period character, can't contain any of '!@#$%^&'\"*()+=:;/', and can't have adjacent periods.";

const DEFAULT_PORTS = new Map([
  ['ftp', 21],
  ['ssh', 22],
  ['telnet', 23],
  ['smtp', 25],
  ['http', 80],
  ['pop3', 110],
  ['imap', 143],
  ['ldap', 389],
  ['https', 443],
  ['ws', 80],
  ['wss', 443],
  ['ftps', 990],
]);

export function stripIgnoredCharacters(url) {
  return url.replace(/[\t\r\n]/g, '');
}

export function dropSchemeAfterLeadingWhitespace(url) {
  if (!/^\s/.test(url)) {
    return url;
  }

  const trimmed = url.replace(/^\s+/, '');
  return trimmed.replace(/^[A-Za-z][A-Za-z0-9+.-]*:/, '');
}

export function splitUrl(url) {
  let rest = url;
  let fragment = '';
  let query = '';

  const fragmentIndex = rest.indexOf('#');
  if (fragmentIndex !== -1) {
    fragment = rest.slice(fragmentIndex + 1);
    rest = rest.slice(0, fragmentIndex);
  }

  const queryIndex = rest.indexOf('?');
  if (queryIndex !== -1) {
    query = rest.slice(queryIndex + 1);
    rest = rest.slice(0, queryIndex);
  }

  let scheme = '';
  const schemeMatch = /^([A-Za-z][A-Za-z0-9+.-]*):(.*)$/.exec(rest);
  if (schemeMatch !== null) {
    scheme = schemeMatch[1].toLowerCase();
    rest = schemeMatch[2];
  }

  let netloc = null;
  let path = rest;
  if (rest.startsWith('//')) {
    const withoutSlashes = rest.slice(2);
    const pathIndex = withoutSlashes.indexOf('/');
    if (pathIndex === -1) {
      netloc = withoutSlashes;
      path = '';
    } else {
      netloc = withoutSlashes.slice(0, pathIndex);
      path = withoutSlashes.slice(pathIndex);
    }
  }

  return { scheme, netloc, path, query, fragment };
}

export function invalidHostError(host) {
  return new Error(`Invalid host '${host}'. ${HOST_ERROR_SUFFIX}`);
}

export function normalizeHost(host) {
  if (host === '') {
    return '';
  }

  if (host.startsWith('[')) {
    if (!host.endsWith(']')) {
      throw invalidHostError(host);
    }

    const inner = host.slice(1, -1);
    const zoneIndex = inner.indexOf('%25');
    const address = zoneIndex === -1 ? inner : inner.slice(0, zoneIndex);
    if (isIP(address) !== 6) {
      throw new Error(`'${inner}' does not appear to be an IPv4 or IPv6 address`);
    }
    return `[${inner.toLowerCase()}]`;
  }

  if (
    INVALID_HOST_CHARS.test(host) ||
    !/[^.]/.test(host) ||
    host.startsWith('.') ||
    host.includes('..')
  ) {
    throw invalidHostError(host);
  }

  if (/[^\x00-\x7f]/.test(host)) {
    const ascii = domainToASCII(host);
    if (ascii === '') {
      throw invalidHostError(host);
    }
    return ascii.toLowerCase();
  }

  return host.toLowerCase();
}

export function normalizePort(port) {
  if (port === null) {
    return null;
  }

  if (!/^\d+$/.test(port)) {
    throw new Error(`Invalid port '${port}'.`);
  }

  const value = Number.parseInt(port, 10);
  if (value < 1 || value > 65535) {
    throw new Error(`Invalid port '${port}'.`);
  }
  return value;
}

export function parseNetloc(netloc) {
  let hostPort = netloc;
  let username = null;
  let password = null;

  const authIndex = hostPort.lastIndexOf('@');
  if (authIndex !== -1) {
    const userinfo = hostPort.slice(0, authIndex);
    hostPort = hostPort.slice(authIndex + 1);

    const passwordIndex = userinfo.indexOf(':');
    if (passwordIndex === -1) {
      username = userinfo;
    } else {
      username = userinfo.slice(0, passwordIndex);
      password = userinfo.slice(passwordIndex + 1);
    }
  }

  let host;
  let port = null;
  if (hostPort.startsWith('[')) {
    const closingIndex = hostPort.indexOf(']');
    if (closingIndex === -1) {
      throw invalidHostError(hostPort);
    }

    host = hostPort.slice(0, closingIndex + 1);
    const remainder = hostPort.slice(closingIndex + 1);
    if (remainder !== '') {
      if (!remainder.startsWith(':')) {
        throw invalidHostError(hostPort);
      }
      port = remainder.slice(1);
    }
  } else {
    const portIndex = hostPort.lastIndexOf(':');
    if (portIndex === -1) {
      host = hostPort;
    } else {
      host = hostPort.slice(0, portIndex);
      port = hostPort.slice(portIndex + 1);
    }
  }

  return {
    username,
    password,
    host: normalizeHost(host),
    port: normalizePort(port),
  };
}

export function normalizePath(path) {
  return quote(unquote(path), PATH_SAFE);
}

export function normalizeFragment(fragment) {
  return quote(unquote(fragment), FRAGMENT_SAFE);
}

export function serializeNetloc({ username, password, host, port }, scheme) {
  let netloc = '';

  if (username !== null) {
    netloc += quote(unquote(username), '');
    if (password !== null) {
      netloc += `:${quote(unquote(password), '')}`;
    }
    netloc += '@';
  }

  netloc += host;

  if (port !== null && DEFAULT_PORTS.get(scheme) !== port) {
    netloc += `:${port}`;
  }

  return netloc;
}

import { parseQuery, serializeQuery } from './pythonCodec.mjs';
import {
  dropSchemeAfterLeadingWhitespace,
  normalizeFragment,
  normalizeHost,
  normalizePath,
  parseNetloc,
  serializeNetloc,
  splitUrl,
  stripIgnoredCharacters,
} from './urlParts.mjs';

export class Furl {
  constructor(url) {
    const cleaned = dropSchemeAfterLeadingWhitespace(
      stripIgnoredCharacters(String(url)),
    );
    const parts = splitUrl(cleaned);

    this.scheme = parts.scheme;
    this.path = parts.path;
    this.query = parts.query;
    this.fragment = parts.fragment;
    this.queryPairs = parseQuery(parts.query);

    if (parts.netloc === null) {
      this.username = null;
      this.password = null;
      this.host = null;
      this.port = null;
    } else {
      const netloc = parseNetloc(parts.netloc);
      this.username = netloc.username;
      this.password = netloc.password;
      this.host = netloc.host;
      this.port = netloc.port;
    }
  }

  set({ host }) {
    this.host = normalizeHost(String(host));
    return this;
  }

  get url() {
    const netloc = serializeNetloc(
      {
        username: this.username,
        password: this.password,
        host: this.host,
        port: this.port,
      },
      this.scheme,
    );

    let output = '';
    if (this.scheme !== '') {
      output += `${this.scheme}:`;
    }
    output += `//${netloc}`;

    const path = normalizePath(this.path);
    if (path !== '') {
      output += path.startsWith('/') ? path : `/${path}`;
    }

    const query = serializeQuery(this.queryPairs);
    if (query !== '') {
      output += `?${query}`;
    }

    if (this.fragment !== '') {
      output += `#${normalizeFragment(this.fragment)}`;
    }

    return output;
  }
}

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function programName() {
  const script = process.argv[1] ?? 'test2.mjs';
  return script.split(/[\\/]/).pop() || 'test2.mjs';
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function printHelp(prog) {
  console.log(`${usageLine(prog)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`);
}

function fail(prog, message) {
  console.error(usageLine(prog));
  console.error(`${prog}: error: ${message}`);
  process.exit(2);
}

function isOptionLike(token) {
  return token === '--' || (token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER.test(token));
}

export function parseArguments(argv) {
  const prog = programName();
  const values = { a: undefined, b: undefined };
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      printHelp(prog);
      process.exit(0);
    }

    if (token === '--') {
      unknown.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--') && token.includes('=')) {
      const equalsIndex = token.indexOf('=');
      const option = token.slice(0, equalsIndex);
      if (option === '--a' || option === '--b') {
        values[option.slice(2)] = token.slice(equalsIndex + 1);
      } else {
        unknown.push(token);
      }
      continue;
    }

    if (token === '--a' || token === '--b') {
      const next = argv[index + 1];
      if (next === undefined || isOptionLike(next)) {
        fail(prog, `argument ${token}: expected one argument`);
      }
      values[token.slice(2)] = next;
      index += 1;
      continue;
    }

    if (isOptionLike(token)) {
      unknown.push(token);
      const next = argv[index + 1];
      if (next !== undefined && !isOptionLike(next)) {
        unknown.push(next);
        index += 1;
      }
      continue;
    }

    unknown.push(token);
  }

  const missing = [];
  if (values.a === undefined) {
    missing.push('--a');
  }
  if (values.b === undefined) {
    missing.push('--b');
  }
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (unknown.length > 0) {
    fail(prog, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return values;
}

import { parseArguments } from './lib/args.mjs';
import { Furl } from './lib/furl.mjs';

const args = parseArguments(process.argv.slice(2));

try {
  const f = new Furl(args.a);
  console.log(f.set({ host: args.b }).url);
} catch (error) {
  if (error instanceof Error) {
    console.error(`ValueError: ${error.message}`);
  } else {
    console.error(String(error));
  }
  process.exit(1);
}

