  let output = '';
  let chunk = '';
  let index = 0;

  const flushChunk = () => {
    if (chunk !== '') {
      output += quote(unquote(chunk), safe);
      chunk = '';
    }
  };

  while (index < value.length) {
    if (
      value[index] === '%' &&
      index + 2 < value.length &&
      isHexDigit(value[index + 1]) &&
      isHexDigit(value[index + 2])
    ) {
      const byte = Number.parseInt(value.slice(index + 1, index + 3), 16);
      if (protectedBytes.has(byte)) {
        flushChunk();
        output += `%${HEX[(byte >> 4) & 0x0f]}${HEX[byte & 0x0f]}`;
